   934  size_t Curl_ftp_parselist(char *buffer, size_t size, size_t nmemb,
   935                            void *connptr)
   936  {
   937    size_t bufflen = size*nmemb;
   938    struct Curl_easy *data = (struct Curl_easy *)connptr;
   939    struct ftp_wc *ftpwc = data->wildcard->ftpwc;
   940    struct ftp_parselist_data *parser = ftpwc->parser;
   941    size_t i = 0;
   942    CURLcode result;
   943    size_t retsize = bufflen;
   944
   945    if(parser->error) { /* error in previous call */
   946      /* scenario:
   947       * 1. call => OK..
   948       * 2. call => OUT_OF_MEMORY (or other error)
   949       * 3. (last) call => is skipped RIGHT HERE and the error is handled later
   950       *    in wc_statemach()
   951       */
   952      goto fail;
   953    }
   954
   955    if(parser->os_type == OS_TYPE_UNKNOWN && bufflen > 0) {
   956      /* considering info about FILE response format */
   957      parser->os_type = ISDIGIT(buffer[0]) ? OS_TYPE_WIN_NT : OS_TYPE_UNIX;
   958    }
   959
   960    while(i < bufflen) { /* FSM */
   961      char c = buffer[i];
   962      struct fileinfo *infop;
   963      if(!parser->file_data) { /* tmp file data is not allocated yet */
   964        parser->file_data = Curl_fileinfo_alloc();
   965        if(!parser->file_data) {
   966          parser->error = CURLE_OUT_OF_MEMORY;
   967          goto fail;
   968        }
   969        parser->item_offset = 0;
   970        parser->item_length = 0;
   971        curlx_dyn_init(&parser->file_data->buf, MAX_FTPLIST_BUFFER);
   972      }
   973
   974      infop = parser->file_data;
   975
   976      if(curlx_dyn_addn(&infop->buf, &c, 1)) {
   977        parser->error = CURLE_OUT_OF_MEMORY;
   978        goto fail;
   979      }
   980
   981      switch(parser->os_type) {
   982      case OS_TYPE_UNIX:
   983        result = parse_unix(data, parser, infop, c);
   984        break;
   985      case OS_TYPE_WIN_NT:
   986        result = parse_winnt(data, parser, infop, c);
   987        break;
   988      default:
   989        retsize = bufflen + 1;
   990        goto fail;
   991      }
   992      if(result) {
   993        parser->error = result;
   994        goto fail;
   995      }
   996
   997      i++;
   998    }
   999    return retsize;
  1000
  1001  fail:
  1002
  1003    /* Clean up any allocated memory. */
  1004    if(parser->file_data) {
  1005      Curl_fileinfo_cleanup(parser->file_data);
  1006      parser->file_data = NULL;
  1007    }
  1008
